+/** Turns one glob (without its `!`) into an anchored regex over a whole `/`-separated path. */
+function compileGlob(glob: string): RegExp {
+  const segments = glob.split("/");
+  let re = "";
+  // Whether `re` already ends where a separator would go (start of path, or after a `**/` piece).
+  let atBoundary = true;
+
+  segments.forEach((segment, index) => {
+    const isLast = index === segments.length - 1;
+    if (!atBoundary) re += "/";
+
+    if (segment === "**" && !isLast) {
+      // Zero or more whole segments, each followed by a separator.
+      re += "(?:[^/]+/)*";
+      atBoundary = true;
+      return;
+    }
+
+    if (segment === "**") {
+      // Trailing `**`: at least one character, so `src/**` does not match `src`.
+      re += ".+";
+      atBoundary = false;
+      return;
+    }
+
+    let i = 0;
+    while (i < segment.length) {
+      const ch = segment[i];
+      if (ch === "*") {
+        while (segment[i + 1] === "*") i++;
+        re += "[^/]*";
+      } else if (ch === "?") {
+        re += "[^/]";
+      } else {
+        re += ch.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
+      }
+      i++;
+    }
+    atBoundary = false;
+  });
+
+  return new RegExp(`^${re}$`, "s");
+}
